import SwiftUI
struct JobsView: View { @State private var requestedAction: SwipeAction?; @State private var badgeAction: SwipeAction?; var body: some View { NavigationStack { VStack(spacing:10){ CardStackView(actionRequest:$requestedAction,badgeAction:$badgeAction).frame(maxHeight:.infinity); ActionBadgeView(action:badgeAction){badgeAction=nil}.frame(height:34); HStack(spacing:28){ actionButton("xmark",.dislike,DS.ColorToken.textMuted); actionButton("star.fill",.star,DS.ColorToken.gold); actionButton("checkmark",.queue,DS.ColorToken.primary) }.padding(.bottom,10) }.background(DS.ColorToken.background.ignoresSafeArea()).toolbar{ToolbarItem(placement:.principal){Text("Jobs").font(.system(size:17,weight:.semibold))}; ToolbarItem(placement:.topBarTrailing){Button{HapticManager.shared.softTap()}label:{Image(systemName:"line.3.horizontal.decrease.circle")}}} } }
    private func actionButton(_ image:String,_ action:SwipeAction,_ color:Color)->some View { Button{switch action{case .star:HapticManager.shared.star(); case .dislike,.skip:HapticManager.shared.dismiss(); default:HapticManager.shared.trigger()}; requestedAction=action} label:{Image(systemName:image).font(.system(size:18,weight:.semibold))}.buttonStyle(MinimalButton(foreground:color)) }
}
